"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000000, '9c8b7259-de7f-5a31-8f39-515f70e2b999', 0, '2026-11-16 19:33:33', 100, 'T', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#1-sales-order', 'Y', '1 · Sales Order', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000000, 1000000, '9c9ac7c9-c759-5df2-aa0b-3b77c4aa9a1f', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p>Open <b><a href=\"#\" data-help-win=\"143\">Sales Order</a></b> from the menu (⌂ → Sales), create a line or two, and press the <b>Process</b> button (§6) → <b>Complete</b>. Completion is not just a status flip: <code>completeIt</code> fans out into the shipment and invoice that follow it, in the SAME signed op-group.</p>', '2026-11-16 19:33:33', 100)",
"UPDATE ad_tab SET ad_ctxhelp_id=1000000 WHERE ad_tab_id=186 AND ad_ctxhelp_id IS NULL",
"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000001, 'f02888ee-9284-5d0e-ba81-9b2ac95b1d73', 0, '2026-11-16 19:33:33', 100, 'T', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment', 'Y', '2 · Shipment', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000001, 1000001, 'acd8379a-62f4-576a-8360-00e12acc2d7d', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p>The <b>Shipment</b> (<code><a href=\"#\" data-help-win=\"169\">M_InOut</a></code>) that Complete generated is a real window of its own (⌂ → Inventory → Shipment) — open it to see the same document from the warehouse side. On-hand for every shipped product drops immediately; the shipment also carries its own GL leg (Cost of Goods Sold against Inventory), not just a paper movement.</p>', '2026-11-16 19:33:33', 100)",
"UPDATE ad_tab SET ad_ctxhelp_id=1000001 WHERE ad_tab_id=257 AND ad_ctxhelp_id IS NULL",
"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000002, 'bd85fcf0-cdba-5d0a-9e6c-6045558f085b', 0, '2026-11-16 19:33:33', 100, 'T', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#3-customer-invoice-ar', 'Y', '3 · Customer Invoice → AR', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000002, 1000002, '06cdc047-08a5-56b7-a4c4-d36502601ed4', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p>The <b><a href=\"#\" data-help-win=\"167\">Invoice</a></b> the same Complete generated posts DR <b>Receivable</b> / CR <b>Revenue</b> (per line) / CR <b>Tax Due</b>. Open <b>Posting Preview</b> on the invoice (any completed document has this) to see that exact journal before you take our word for it — it is the SAME derivation the guide''s Posting-Preview panel runs live, not a separate report-only calculation.</p>', '2026-11-16 19:33:33', 100)",
"UPDATE ad_tab SET ad_ctxhelp_id=1000002 WHERE ad_tab_id=263 AND ad_ctxhelp_id IS NULL",
"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000003, '3c78e5c2-8a11-5d0b-869a-974294624c1a', 0, '2026-11-16 19:33:33', 100, 'T', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#4-receipt-allocation', 'Y', '4 · Receipt & Allocation', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000003, 1000003, 'b6cef894-e0cc-55d1-9ed3-77269eeac1c9', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p>Record the customer''s <b><a href=\"#\" data-help-win=\"195\">Payment</a></b> (⌂ → Sales → Payment) against the invoice, then run <b><a href=\"#\" data-help-win=\"205\">Allocation</a></b> to match payment to invoice. A real allocation is rarely an exact match — it can carry a discount, a write-off, and (because tax rides the discounted portion too) a VAT correction, all in the same posting.</p>', '2026-11-16 19:33:33', 100)",
